import bisect

class RateLimiter:
    def __init__(self, max_requests, window):
        self.max_requests = max_requests
        self.window = window
        self.request_times = {}

    def allow(self, key: str, now: float) -> bool:
        if key in self.request_times:
            return bisect.bisect_left(self.request_times[key], now) == len(self.request_times[key])

        if len(self.request_times) < self.max_requests:
            self.request_times[key] = []
            self.request_times[key].append(now)
            return True

        if now - self.request_times[key][0] < self.window:
            return False

        del self.request_times[key]
        self.request_times[key] = [now]

        bisect.insort(self.request_times[key], *self.request_times.pop(key))

        return True

